def dataset():
    documents, queries = [], []
    for key, title, current, similar, archived, questions in TOPICS:
        for variant, text in (("current", current), ("similar", similar), ("archived", archived)):
            documents.append({"key": f"{key}-{variant}", "title": f"{title} — {variant}",
                              "text": f"# {title}\n\n{text}", "topic": key, "variant": variant})
        for kind, (question, grades) in zip(("exact", "paraphrase", "confounder", "synthesis", "historical", "ambiguous"), questions):
            queries.append({"key": f"{key}-{kind}", "q": question, "kind": kind,
                            "split": "development" if len(queries) % 5 == 0 else "evaluation",
                            "relevance": {f"{key}-{variant}": grade for variant, grade in grades.items()}})
    return {"version": 1, "unit": "document (deduplicate chunks before scoring)",
            "labelPolicy": "3 directly answers; 2 relevant to deliberately ambiguous symptom; archived sources relevant only to historical questions",
            "documents": documents, "queries": queries}


if __name__ == "__main__":
    output = Path(__file__).resolve().parents[2] / "evaluations/m15/retrieval-dataset.json"
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(dataset(), indent=2, ensure_ascii=False) + "\n")
